package com.instagram.insfav.fetcher;
import android.content.*;
import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;
import java.util.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk={28,34},manifest=Config.NONE)
public class IntegrationQueueTest{
 Context c;
 @Before public void setup(){c=RuntimeEnvironment.getApplication();c.deleteDatabase("fetcher-queue.db");SessionState.prefs(c).edit().clear().commit();}
 @Test public void deduplicatesAndPreservesDurableStatuses(){try(QueueStore q=new QueueStore(c)){q.sync(Arrays.asList("one","one","two","three"));q.mark("one","SUCCESS","VALID_WEBP");q.mark("two","SKIPPED_UNAVAILABLE","PROFILE_NOT_FOUND_OR_UNAVAILABLE");q.mark("three","RETRY_LATER","NETWORK_ERROR");q.attempted("three");}try(QueueStore q=new QueueStore(c)){q.sync(Arrays.asList("one","two","three"));assertEquals(3,q.users(false).size());assertEquals(Integer.valueOf(1),q.counts().get("SUCCESS"));assertEquals(Integer.valueOf(1),q.counts().get("SKIPPED_UNAVAILABLE"));assertEquals(Arrays.asList("three"),q.eligible());}}
 @Test public void missingUrlIsRetryNotDeletedAndCannotBlockWholeQueue(){assertFalse(FailurePolicy.unavailable(new ProfileProvider.Failure("PROFILE_IMAGE_URL_MISSING",200,0,false)));assertFalse(FailurePolicy.pause(new ProfileProvider.Failure("PROFILE_IMAGE_URL_MISSING",200,0,false)));assertFalse(FailurePolicy.pause(new ProfileProvider.Failure("WEBVIEW_NETWORK_ERROR",0,0,true)));assertFalse(FailurePolicy.pause(new ProfileProvider.Failure("PROFILE_PAGE_UNAVAILABLE",200,0,true)));}
 @Test public void confirmedUnavailableAdvancesAndRetriesAreBounded(){try(QueueStore q=new QueueStore(c)){q.sync(Arrays.asList("gone","later","good"));q.mark("gone","SKIPPED_UNAVAILABLE","PROFILE_NOT_FOUND_OR_UNAVAILABLE");q.mark("later","RETRY_LATER","NETWORK_ERROR");for(int i=0;i<3;i++)q.attempted("later");assertEquals(Arrays.asList("good"),q.eligible());}assertTrue(FailurePolicy.unavailable(new ProfileProvider.Failure("PROFILE_NOT_FOUND_OR_UNAVAILABLE",404,0,false)));}
 @Test public void globalSessionAndRateLimitBlocksStayGlobal(){for(ProfileProvider.Failure e:new ProfileProvider.Failure[]{new ProfileProvider.Failure("RATE_LIMITED",429,100,true),new ProfileProvider.Failure("COOKIE_INVALID_EXPIRED",401,0,true),new ProfileProvider.Failure("CHALLENGE_REQUIRED",200,0,true),new ProfileProvider.Failure("PRIVATE_RESTRICTED",403,0,true)})assertTrue(FailurePolicy.pause(e));}
 @Test public void freshStartNeedsNoThreeProfileProof(){SharedPreferences p=SessionState.prefs(c);p.edit().putBoolean("background",true).putBoolean("armed",true).putBoolean("userPaused",false).commit();assertTrue(WorkScheduler.enabled(p));assertFalse(SessionState.verified(p));}
 @Test public void startMissingRecoversLostSuccessfulOutputButLeavesUnavailableAlone(){try(QueueStore q=new QueueStore(c)){q.sync(Arrays.asList("one","two"));q.mark("one","SUCCESS","VALID_WEBP");q.mark("two","SKIPPED_UNAVAILABLE","PROFILE_NOT_FOUND_OR_UNAVAILABLE");q.prepareMissing();q.requeueLost("one");assertEquals(Arrays.asList("one"),q.eligible());}}
}
